from pysat.card import CardEnc, EncType
from pysat.formula import CNF
from pysat.solvers import Glucose4

G, S, W = 9, 4, 6
N = G * S  # 36

# Variable x[w][p][g] = golfer p is in group g on week w
def var(w, p, g):
    return w * N * G + p * G + g + 1

top = W * N * G

cnf = CNF()
vpool_next = [top + 1]
def new_var():
    v = vpool_next[0]
    vpool_next[0] += 1
    return v

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(N):
        lits = [var(w,p,g) for g in range(G)]
        # exactly one
        cnf.append(lits)
        for i in range(len(lits)):
            for j in range(i+1, len(lits)):
                cnf.append([-lits[i], -lits[j]])

# Each group has exactly S players per week
for w in range(W):
    for g in range(G):
        lits = [var(w,p,g) for p in range(N)]
        enc = CardEnc.equals(lits=lits, bound=S, top_id=vpool_next[0]-1, encoding=EncType.seqcounter)
        for cl in enc.clauses:
            cnf.append(cl)
            for l in cl:
                if abs(l) >= vpool_next[0]:
                    vpool_next[0] = abs(l)+1

# Pair constraint: for each pair p<q, sum over w,g of (p in g week w AND q in g week w) <= 1
# Introduce meet[w][p][q][g] = var(w,p,g) AND var(w,q,g)
# Actually easier: for each pair (p,q), sum_{w,g} AND <= 1
# Use auxiliary: m_wg = x[w,p,g] & x[w,q,g]
# Then sum m_wg <= 1

for p in range(N):
    for q in range(p+1, N):
        ms = []
        for w in range(W):
            for g in range(G):
                m = new_var()
                a = var(w,p,g); b = var(w,q,g)
                # m <-> a AND b
                cnf.append([-m, a])
                cnf.append([-m, b])
                cnf.append([m, -a, -b])
                ms.append(m)
        # at most 1 among ms
        enc = CardEnc.atmost(lits=ms, bound=1, top_id=vpool_next[0]-1, encoding=EncType.seqcounter)
        for cl in enc.clauses:
            cnf.append(cl)
            for l in cl:
                if abs(l) >= vpool_next[0]:
                    vpool_next[0] = abs(l)+1

# Symmetry breaking: week 0 fixed: golfer p in group p//S
for p in range(N):
    cnf.append([var(0, p, p//S)])

# Week 1 symmetry: golfer 0..3 in groups 0..3 (one per)
for i in range(S):
    cnf.append([var(1, i, i)])

print("clauses", len(cnf.clauses), "vars", vpool_next[0]-1)

solver = Glucose4()
for cl in cnf.clauses:
    solver.add_clause(cl)

result = solver.solve()
print("SAT?", result)
if result:
    model = set(solver.get_model())
    sched = []
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if var(w,p,g) in model:
                    sched.append(g)
                    break
    print(len(sched))
    # verify
    ok = True
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(sched[w*N+p], []).append(p)
        for g,ps in groups.items():
            if len(ps)!=S: ok=False
    # pair check
    pair_count = {}
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(sched[w*N+p], []).append(p)
        for g,ps in groups.items():
            for i in range(len(ps)):
                for j in range(i+1,len(ps)):
                    key=(ps[i],ps[j])
                    pair_count[key]=pair_count.get(key,0)+1
    if any(v>1 for v in pair_count.values()): ok=False
    print("valid", ok)
    print(sched)
